def main():
    O.mkdir(exist_ok=False);audit=read(D/'substep_audit_v2_190/independent_audit.json');diag=read(D/'substep_diagnosis_v3_191/results.json');video=read(D/'all_attempts_video_audit_193/independent_audit.json')
