    paths=[D/'substep_revision_189.json',D/'substep_launch_recovery_189.json',D/'substep_shutdown_recovery_189/recovery.json',D/'substep_audit_recovery_190/recovery.json',D/'substep_diagnosis_recovery_191/recovery.json',D/'substep_diagnostic_189/diagnostic_protocol.json',D/'substep_diagnostic_189/diagnostic_accounting.json',D/'substep_diagnostic_189/actuator_metadata.json',D/'substep_audit_v2_190/independent_audit.json',D/'substep_diagnosis_v3_191/results.json',D/'all_attempts_video_audit_193/independent_audit.json']
